import sys

def can_form_palindrome(s):
    n = len(s)
    for i in range(n + 1):
        for c in 'abcdefghijklmnopqrstuvwxyz':
            new_s = s[:i] + c + s[i:]
            if new_s == new_s[::-1]:
                return new_s
    return "NA"

s = sys.stdin.read().strip()
print(can_form_palindrome(s))
